interface Circle { kind: "circle"; radius: number }
interface Rect { kind: "rect"; width: number; height: number }
// TODO: Triangle with three sides

type Shape = Circle | Rect;

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.radius ** 2;
    default:
      return 0;
  }
}
